def lru_cache_sim(capacity, operations):
    cache = OrderedDict()
    for op, key, *value in operations:
        if op == 'get':
            result = -1 if key not in cache else value[0]
            if key in cache:
                del cache[key]
            if len(cache) >= capacity:
                cache.popitem(last=False)
            cache[key] = (result, None)
        elif op == 'put':
            if key in cache:
                del cache[key]
            if len(cache) >= capacity:
                cache.popitem(last=False)
            cache[key] = value
    return dict(cache)
